class Solution { fun avoidFlood(rains:IntArray):IntArray{val answer=IntArray(rains.size){1};val lastRain=mutableMapOf<Int,Int>();val dryDays=java.util.TreeSet<Int>();for(day in rains.indices)if(rains[day]==0)dryDays.add(day)else{val lake=rains[day];answer[day]=-1;if(lake in lastRain){val dry=dryDays.higher(lastRain.getValue(lake))?:return intArrayOf();answer[dry]=lake;dryDays.remove(dry)};lastRain[lake]=day};return answer} }
